#include "pc_draw_distance.h"

/* Lightning (B2): tell the PC draw path (nv2a_pb_exec.c) when the env flashes (+0x16C) and the sun colour (+0x88). */
#include <string.h>
#include <stdio.h>
extern volatile int g_lt_flash_on; extern float g_lt_sun_col[3];
static void lt_env_update(uint32_t env)
{
    int flashing = env && MEM8(env + 0x16C) != 0;
    {   /* diag RECOMP_OVERLAY_TRACE (R27 tint2): log lightning flash on/off with the env sun colour */
        extern FILE *nv2a_overlay_trace_file(void); FILE *of = nv2a_overlay_trace_file();
        if (of && flashing != g_lt_flash_on) { float c[3]; for (int i = 0; i < 3; i++) { uint32_t v = env ? MEM32(env + 0x88 + 4 * i) : 0; memcpy(&c[i], &v, 4); }
            fprintf(of, "L %u %d env=%08X sun=%.3f,%.3f,%.3f cached=%.3f,%.3f,%.3f\n", MEM32(0x4E2420), flashing, env, c[0], c[1], c[2], g_lt_sun_col[0], g_lt_sun_col[1], g_lt_sun_col[2]); }
    }
    g_lt_flash_on = flashing;
    if (env && !flashing) for (int i = 0; i < 3; i++) { uint32_t v = MEM32(env + 0x88 + 4 * i); memcpy(&g_lt_sun_col[i], &v, 4); }
}
    lt_env_update(eax);
    ma2_pc_fog_distance(edi,&MEMF(esp),&MEMF(esp+4));
